#!/usr/bin/env python3
"""Generate reports/joint_ns_queueing_mechanism_report.md from the analysis JSONs."""
import json
import os
import time

BASE = "/workspaces/mvp/testdata/live_joint_ns_queueing"
J = json.load(open(os.path.join(BASE, "analysis", "gate_analysis.json")))
CAL = json.load(open(os.path.join(BASE, "calibration", "model_calibration.json")))
D = json.load(open(os.path.join(BASE, "manifest", "gate_design.json")))
STATES = ["S0_no_background", "S1_moderate", "S2_heavy"]
N_GRID = [1, 2, 4, 8, 16]


def c(st, n):
    return J["states"][st]["cells"][str(n)]


def s(st):
    return J["states"][st]["summary"]


L = []
a = L.append
a("# Live Joint N+S Queueing Mechanism — Gate Report")
a("")
a("**Status: `NO_LIVE-GROUNDED_JOINT_N+S_OPPORTUNITY`.** The live shared-bottleneck")
a("mechanism gate FAILED: the mechanism produces a measurable queueing/contention cost")
a("that grows with N, but it does **not** produce a finite/interior concurrency optimum")
a("and no material state-dependent N*. Per the frozen stop rule, no S sweep, no adaptive")
a("controller, and no confirmatory protocol were created.")
a("")
a("Generated: %s" % time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()))
a("")
a("## 1. Why the fixed D2 win is not an adaptive result")
a("")
a("The frozen aria2-competitive benchmark established a reproducible 62.4 % completion-")
a("time advantage for a **fixed** configuration (N=16, S=4 MiB) over fixed aria2")
a("(split=16) under the D2 workload (geometric ratio 0.3756, 30/30 pairs). The")
a("configuration never changes during a download, so the result is a fixed-scheduler")
a("result, not adaptation. The joint N+S analytical screen (§22.90) then showed that the")
a("D2 per-response pacing mechanism has no causal joint-adaptation headroom (N*=16 in")
a("every regime; only S varies; every causal controller lost to the best fixed config).")
a("This study tested one final mechanism branch — a live shared bottleneck with")
a("queueing — before deciding whether genuine joint N+S adaptation is defensible.")
a("")
a("## 2. Shared-bottleneck mechanism")
a("")
a("Traffic path: internal downloader + independent background traffic -> one finite-")
a("capacity FIFO bottleneck -> queueing delay, RTT inflation, drops, retransmissions.")
a("The bottleneck is a real `tc tbf` qdisc on `lo` (rate 40 Mbit/s, burst 32 kb,")
a("limit 256 kb; maximum queueing delay ~46 ms), with the loopback MTU temporarily set")
a("to 1500 to emulate a realistic Ethernet-like path (restored after the study). The")
a("mechanism is NOT merely bandwidth sharing: the required phenomenon was an increasing")
a("queueing/inefficiency penalty with N, i.e. a finite interior N optimum.")
a("")
a("## 3. Infrastructure (all live; no simulator)")
a("")
a("- `tools/gate_run.go` — one real download (internal downloader, fixed N/S, logical")
a("  32 MiB object, no application-level pacing), content-verified, with the server")
a("  request log.")
a("- `tools/run_gate.py` — driver: tbf apply/clear, fresh iperf3 background server+client")
a("  per cell (retried and explicitly verified), concurrent ping RTT sampling, qdisc")
a("  backlog/drop counters, nstat retransmission/timeout deltas, load.")
a("- Contention states (predeclared, grounded in C): S0 B=0; S1 B=0.5C=20 Mbit/s;")
a("  S2 B=0.85C=34 Mbit/s. Background: iperf3, 4 paced TCP streams.")
a("- Download: 32 MiB, S=1 MiB, N in {1,2,4,8,16}, 3 reps/cell, round-robin; 45/45")
a("  valid runs (content-verified, background verified).")
a("- Infrastructure failures found and fixed **before** the gate measurements: lo MTU")
a("  burst mismatch (downloads stalled), iperf3 `-b` is per stream (units), and")
a("  intermittent iperf3 control-connection resets (cells without background). Invalid")
a("  runs are preserved under `mechanism_gate/invalid/` and excluded.")
a("")
a("## 4. Fixed-N gate (live results)")
a("")
a("| state | N=1 | N=2 | N=4 | N=8 | N=16 | N* | margin |")
a("|---|---|---|---|---|---|---|---|")
for st in STATES:
    meds = s(st)["median_s"]
    a("| %s | %s |" % (st, " | ".join("%.2f" % meds[str(n)] for n in N_GRID)
                       + " | %d | %+.1f%% |" % (s(st)["N_star"], 100 * s(st)["margin"])))
a("")
a("Queueing cost (median p95 RTT, ms):")
a("")
a("| state | N=1 | N=2 | N=4 | N=8 | N=16 | N=16/N=1 |")
a("|---|---|---|---|---|---|---|")
for st in STATES:
    a("| %s | %s | %.2fx |" % (st, " | ".join("%.1f" % c(st, n)["ping_p95_ms"] for n in N_GRID),
                                s(st)["ping_p95_ratio_16_over_1"]))
a("")
a("Drops / retransmissions (medians):")
a("")
a("| state | metric | N=1 | N=2 | N=4 | N=8 | N=16 |")
a("|---|---|---|---|---|---|---|")
for st in STATES:
    a("| %s | qdisc drops | %s |" % (st, " | ".join("%.0f" % c(st, n)["drops"] for n in N_GRID)))
    a("| | TCP retrans | %s |" % " | ".join("%.0f" % c(st, n)["retrans"] for n in N_GRID))
a("")
a("**Interpretation.** The contention cost is real and measurable: the queue inflates")
a("the median RTT from a 0.04 ms no-qdisc baseline to 33-86 ms, p95 up to 94 ms; drops")
a("reach 0-860 per run; retransmissions 0-576. But the **completion time does not show")
a("a finite interior optimum**:")
a("")
a("- S0 (no background): flat, 7.05-7.17 s across N (N*=8 with a 0.3 % margin — noise);")
a("  the queueing/RTT/drop cost grows with N while the completion is work-conserving.")
a("- S1 (0.5C): flat-to-slightly-increasing 14.28-15.13 s; N*=16 with a 3.9 % margin")
a("  (below the 5 % materiality threshold).")
a("- S2 (0.85C): completion falls strongly with N (62.5 s at N=1 to 15.9 s at N=16):")
a("  more downloader flows win a larger TCP share against the paced background (its")
a("  achieved rate falls from 33.4 to 22.9 Mbit/s), so the optimum is at the boundary")
a("  N=16, not interior.")
a("")
a("## 5. Fixed-S gate")
a("")
a("**NOT REACHED.** The N gate failed (no interior optimum, no material state-")
a("dependent N*), so per the frozen stop rule the S sweep was not run.")
a("")
a("## 6. Joint-optimum gate")
a("")
a("**NOT REACHED** (requires the N gate and S gate to pass). No fixed-policy (N,S)")
a("surface was measured live.")
a("")
a("## 7. Within-download transition")
a("")
a("**NOT REACHED.** No background start/stop transition schedule was frozen or run,")
a("because no mechanism passes the N gate.")
a("")
a("## 8. Live measurements (raw evidence)")
a("")
a("- 45 valid runs in `mechanism_gate/runs/` + `mechanism_gate/meta/`; per-run ping")
a("  samples, iperf3 interval rates, qdisc backlog/drops, nstat deltas, load.")
a("- Background-only calibration per state in `mechanism_gate/background_only_*.json`:")
for st in STATES:
    bo = json.load(open(os.path.join(BASE, "mechanism_gate", "background_only_%s.json" % st)))
    off = bo.get("offered_bits_per_second", bo.get("offered_bps", 0) * 8)
    ach = bo.get("achieved_bits_per_second", bo.get("achieved_bps", 0.0))
    a("  - %s: offered %.1f Mbit/s, achieved %.1f Mbit/s." % (st, off / 1e6, ach / 1e6))
a("- Figures: `figures/fig1_completion_vs_N.png` (completion vs N + work-conserving")
a("  prediction), `fig2_rtt_vs_N.png`, `fig3_drops_retrans_vs_N.png`,")
a("  `fig4_background.png`, `fig5_model_vs_live.png`.")
a("")
a("## 9. Analytical calibration")
a("")
a("A deterministic shared-bottleneck model (`tools/queue_model.py`) predicts")
a("`T(N,S|C,B) = F/(C-B_ach(N)) + S/(N(C-B_ach(N))) + k_loss*retrans*MSS/(C-B_ach(N)) + RTT_q`")
a("with one fitted loss coefficient `k_loss=%.1f`. Fitted on the 15 live cell medians:" % CAL["k_loss"])
a("relative RMSE **%.1f %%**, max absolute relative error **%.1f %%**." % (
    100 * CAL["rmse_rel"], 100 * CAL["max_abs_rel"]))
a("The model reproduces the observed pattern: flat/boundary N* with no interior")
a("optimum (predicted N*: S0=%d, S1=%d, S2=%d vs observed S0=%d, S1=%d, S2=%d)." % (
    CAL["predicted_N_star_per_state"]["S0_no_background"],
    CAL["predicted_N_star_per_state"]["S1_moderate"],
    CAL["predicted_N_star_per_state"]["S2_heavy"],
    s("S0_no_background")["N_star"], s("S1_moderate")["N_star"], s("S2_heavy")["N_star"]))
a("The work-conserving bulk term is N-independent, so no interior N optimum is")
a("structurally expected from a shared FIFO bottleneck under TCP; the only N-dependence")
a("is loss recovery (which grows with N but stays small relative to the bulk) and the")
a("TCP share competition (which favors more flows under background contention).")
a("")
a("## 10. Causal adaptive result")
a("")
a("**NOT REACHED.** The frozen rule forbids adaptive execution when the mechanism gate")
a("fails. No adaptive N+S controller was implemented or run, and the frozen action")
a("space / one-switch semantics were never exercised.")
a("")
a("## 11. aria2 comparison")
a("")
a("**NOT REACHED** (reserved for the causal comparison only if the joint gate passes;")
a("aria2 was not run and its frozen configuration was not touched).")
a("")
a("## 12. Stationary control")
a("")
a("S0 (no background) is the stationary no-contention control: the completion time is")
a("flat across N (7.05-7.17 s, <= 1.7 %% spread) and the measured optimum margin is")
a("0.3 %%. There is no adaptation gain to be had in the stationary state either, and")
a("the queueing cost there (RTT 47->86 ms, drops 0->338) is not reflected in completion")
a("time — the defining failure of this mechanism.")
a("")
a("## 13. Exact success/failure gate")
a("")
g = J["gate"]
a("- **G-N1 interior optimum** (measurable contention cost + winning N not the largest")
a("  + >= 5 %% margin + consistent winner): **FAIL** (no state has an interior material")
a("  optimum; states with measurable contention cost: %s)." % ", ".join(
    k for k, v in g["G-N1_interior_optimum"]["contention_cost_measurable_per_state"].items() if v))
a("- **G-N2 state dependence** (N* differs across >= 2 states with materiality +")
a("  consistency): **FAIL** (no material state pair; the S0 vs S1/S2 difference is a")
a("  flat-vs-boundary artifact with < 5 %% margins on the flat side).")
a("- **Overall: FAIL -> `NO_LIVE-GROUNDED_JOINT_N+S_OPPORTUNITY` -> STOP.**")
a("")
a("## 14. Limitations")
a("")
a("- One mechanism instantiation: TCP over a single FIFO token-bucket bottleneck on")
a("  loopback (40 Mbit/s, 256 kb queue, 1500-byte MTU), with paced TCP background")
a("  traffic. Other background classes (UDP floods, many short flows, bursty/ON-OFF)")
a("  or smaller queues could behave differently, but the work-conserving argument that")
a("  removes the interior N optimum is structural for a shared FIFO bottleneck.")
a("- The container shares the host network namespace; shaping was applied only to `lo`,")
a("  was cleared after every cell, and the MTU was restored after the study.")
a("- The queue/MTU choices were fixed during infrastructure validation, before any gate")
a("  measurement was used; all invalid runs are preserved and excluded.")
a("- The analytical model is semi-empirical (one fitted loss coefficient) and is not")
a("  used to justify any adaptive claim.")
a("")
a("## 15. What this means for the project")
a("")
a("The live shared-bottleneck/queueing mechanism is **INSUFFICIENT** for a genuine joint")
a("N+S adaptation study: increasing N produces measurable queueing, RTT inflation, drops")
a("and retransmissions, but no completion-time penalty (work conservation), so N has no")
a("finite interior optimum and no state-dependent N*. Per the task's failure path, no")
a("further mechanism was invented in this task. The remaining defensible competitive")
a("result is the existing **fixed 62.4 % aria2 benchmark** (unchanged).")
a("")
a("## 16. Artifacts")
a("")
a("- `mechanism_gate/` (45 valid runs + metas, background-only calibrations, invalid")
a("  infrastructure runs), `analysis/gate_analysis.json`, `calibration/model_calibration.json`,")
a("  `figures/fig1..fig5`, `manifest/gate_design.json`, `manifest/manifest.json`,")
a("  `tools/gate_run.go`, `tools/run_gate.py`, `tools/analyze_gate.py`,")
a("  `tools/queue_model.py`, `tools/make_figures.py`, `tools/make_report.py`.")
a("")
open(os.path.join(BASE, "reports", "joint_ns_queueing_mechanism_report.md"), "w").write("\n".join(L) + "\n")
print("report written")
